create function public.business_attendance_calculation(p_tenant uuid,p_kind text,v jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare shift_def public.business_shifts%rowtype;assignment public.business_shift_assignments%rowtype;entitlement public.business_leave_entitlements%rowtype;person public.business_staff%rowtype;rowdata record;rows jsonb:='[]';total numeric:=0;scheduled numeric;used numeric;regular numeric;extra numeric;start_at timestamptz;end_at timestamptz;day_on date;fingerprint text;context jsonb:='{}';
begin
 if v->>'staff_id' is not null then select * into person from public.business_staff where tenant_id=p_tenant and id=(v->>'staff_id')::uuid and status='active';if not found then raise exception 'BUSINESS_INVALID_REFERENCE';end if;end if;
 if v->>'project_id' is not null and not exists(select 1 from public.business_projects where tenant_id=p_tenant and id=(v->>'project_id')::uuid and status='active' and operational_state='active') then raise exception 'BUSINESS_PROJECT_CLOSED';end if;
 case p_kind
 when 'shift_assignments' then
  select * into shift_def from public.business_shifts where tenant_id=p_tenant and id=(v->>'shift_id')::uuid and status='active';if not found then raise exception 'BUSINESS_INVALID_REFERENCE';end if;
  start_at:=((v->>'starts_on')::date+shift_def.starts_time) at time zone 'Asia/Ho_Chi_Minh';
  end_at:=((v->>'starts_on')::date+shift_def.ends_time+case shift_def.cross_midnight when 'yes' then interval '1 day' else interval '0 days' end) at time zone 'Asia/Ho_Chi_Minh';
  regular:=extract(epoch from end_at-start_at)/3600-shift_def.break_minutes/60.0;day_on:=(case shift_def.day_rule when 'end_day' then end_at else start_at end at time zone 'Asia/Ho_Chi_Minh')::date;
  if regular<=0 or regular>24 or end_at<=start_at or person.joined_on>(v->>'starts_on')::date then raise exception 'BUSINESS_INVALID_DATE';end if;
  if exists(select 1 from public.business_shift_assignments a where a.tenant_id=p_tenant and a.staff_id=person.id and a.status='posted' and a.starts_at::timestamptz<end_at and a.ends_at::timestamptz>start_at) then raise exception 'BUSINESS_SHIFT_OVERLAP';end if;
  if regular+(select coalesce(sum(regular_hours),0) from public.business_shift_assignments where tenant_id=p_tenant and staff_id=person.id and status='posted' and business_shift_assignments.work_date=day_on)>24 then raise exception 'BUSINESS_ATTENDANCE_EXCEEDED';end if;
  total:=regular;rows:=jsonb_build_array(jsonb_build_object('staffName',person.name,'sourceName',shift_def.name,'workDate',day_on,'regularHours',regular,'startsAt',start_at,'endsAt',end_at,'sourceVersion',shift_def.row_version));context:=jsonb_build_object('workDate',day_on,'startsAt',start_at,'endsAt',end_at,'regularHours',regular,'breakMinutes',shift_def.break_minutes,'overtimeMultiplier',shift_def.overtime_multiplier);
 when 'leave_requests' then
  if v->>'leave_type'='paid' then
   select * into entitlement from public.business_leave_entitlements where tenant_id=p_tenant and id=(v->>'entitlement_id')::uuid and staff_id=person.id and status='active';if not found then raise exception 'BUSINESS_LEAVE_BALANCE_REQUIRED';end if;
  end if;
  for rowdata in select * from public.business_leave_request_lines where tenant_id=p_tenant and request_id=(v->>'id')::uuid and status='active' order by work_date,id loop
   perform public.business_assert_attendance_open(p_tenant,person.id,rowdata.work_date,null);
   if exists(select 1 from public.business_salary_runs sr join public.business_salary_lines sl on sl.tenant_id=sr.tenant_id and sl.salary_run_id=sr.id where sr.tenant_id=p_tenant and sr.status='posted' and sl.staff_id=person.id and rowdata.work_date between sr.starts_on and sr.ends_on) then raise exception 'BUSINESS_RECORD_LOCKED';end if;
   if rowdata.work_date<person.joined_on or v->>'leave_type'='paid' and rowdata.work_date not between entitlement.starts_on and entitlement.ends_on then raise exception 'BUSINESS_INVALID_DATE';end if;
   select coalesce(sum(a.regular_hours),0),md5(coalesce(string_agg(a.id::text||':'||a.row_version::text,'|' order by a.id),'')) into scheduled,fingerprint from public.business_shift_assignments a where a.tenant_id=p_tenant and a.staff_id=person.id and a.work_date=rowdata.work_date and a.status='posted';
   if scheduled<=0 then raise exception 'BUSINESS_SHIFT_REQUIRED';end if;
   select coalesce(sum(t.worked_hours),0)+(select coalesce(sum(l.hours),0) from public.business_leave_request_lines l join public.business_leave_requests h on h.tenant_id=l.tenant_id and h.id=l.request_id and h.status='posted' where l.tenant_id=p_tenant and h.staff_id=person.id and l.work_date=rowdata.work_date and l.status='active') into used from public.business_timecards t where t.tenant_id=p_tenant and t.staff_id=person.id and t.work_date=rowdata.work_date and t.status='posted';
   if used+rowdata.hours>scheduled then raise exception 'BUSINESS_ATTENDANCE_EXCEEDED';end if;
   total:=total+rowdata.hours;rows:=rows||jsonb_build_array(jsonb_build_object('sourceId',rowdata.id,'sourceName',person.name,'workDate',rowdata.work_date,'hours',rowdata.hours,'scheduled',scheduled,'used',used,'sourceVersion',rowdata.row_version,'scheduleHash',fingerprint));
  end loop;
  if v->>'leave_type'='paid' then
   select coalesce(sum(total_hours),0) into used from public.business_leave_requests where tenant_id=p_tenant and entitlement_id=entitlement.id and status='posted' and leave_type='paid';
   if used+total>entitlement.allowed_hours+entitlement.carry_hours then raise exception 'BUSINESS_LEAVE_EXCEEDED';end if;context:=jsonb_build_object('entitlementVersion',entitlement.row_version,'remainingBefore',entitlement.allowed_hours+entitlement.carry_hours-used);
  end if;
 when 'overtime_requests','attendance_confirmations' then
  select * into assignment from public.business_shift_assignments where tenant_id=p_tenant and id=(v->>'assignment_id')::uuid and staff_id=person.id and status='posted' and project_id is not distinct from (v->>'project_id')::uuid;if not found then raise exception 'BUSINESS_INVALID_REFERENCE';end if;
  perform public.business_assert_attendance_open(p_tenant,person.id,assignment.work_date,assignment.project_id);
  if p_kind='overtime_requests' then
   if (v->>'work_date')::date<>assignment.work_date or (v->>'hours')::numeric+(select coalesce(sum(hours),0) from public.business_overtime_requests where tenant_id=p_tenant and assignment_id=assignment.id and status='posted')>24-assignment.regular_hours then raise exception 'BUSINESS_ATTENDANCE_EXCEEDED';end if;
   total:=(v->>'hours')::numeric;rows:=jsonb_build_array(jsonb_build_object('staffName',person.name,'workDate',assignment.work_date,'hours',total,'sourceVersion',assignment.row_version));
  else
   start_at:=(assignment.starts_on+(v->>'check_in_time')::time) at time zone 'Asia/Ho_Chi_Minh';
   end_at:=(assignment.starts_on+(v->>'check_out_time')::time+make_interval(days=>(v->>'checkout_day_offset')::integer)) at time zone 'Asia/Ho_Chi_Minh';
   total:=extract(epoch from end_at-start_at)/3600-(assignment.calculation_snapshot->'context'->>'breakMinutes')::numeric/60;
   if total<=0 or total>24 or end_at<=start_at or end_at>now() or (v->>'document_date')::date<(end_at at time zone 'Asia/Ho_Chi_Minh')::date then raise exception 'BUSINESS_INVALID_DATE';end if;
   if exists(select 1 from public.business_attendance_confirmations c where c.tenant_id=p_tenant and c.staff_id=person.id and c.status='posted' and (c.calculation_snapshot->'rows'->0->>'startsAt')::timestamptz<end_at and (c.calculation_snapshot->'rows'->0->>'endsAt')::timestamptz>start_at) then raise exception 'BUSINESS_SHIFT_OVERLAP';end if;
   regular:=least(total,assignment.regular_hours);extra:=greatest(0,total-regular);
   select coalesce(sum(hours),0) into scheduled from public.business_overtime_requests where tenant_id=p_tenant and assignment_id=assignment.id and status='posted';
   if extra>scheduled then raise exception 'BUSINESS_OVERTIME_APPROVAL_REQUIRED';end if;
   select coalesce(sum(worked_hours+overtime_hours),0) into used from public.business_timecards where tenant_id=p_tenant and staff_id=person.id and work_date=assignment.work_date and status='posted';
   if total+used>24 then raise exception 'BUSINESS_ATTENDANCE_EXCEEDED';end if;
   rows:=jsonb_build_array(jsonb_build_object('staffName',person.name,'workDate',assignment.work_date,'regularHours',regular,'overtimeHours',extra,'startsAt',start_at,'endsAt',end_at,'sourceVersion',assignment.row_version));context:=jsonb_build_object('regularHours',regular,'overtimeHours',extra,'workDate',assignment.work_date,'assignmentVersion',assignment.row_version,'approvedOvertime',scheduled,'overtimeMultiplier',assignment.calculation_snapshot->'context'->'overtimeMultiplier');
  end if;
 when 'attendance_locks' then
  if (v->>'starts_on')::date>(v->>'ends_on')::date or (v->>'ends_on')::date-(v->>'starts_on')::date>366 then raise exception 'BUSINESS_INVALID_DATE';end if;
  if exists(select 1 from public.business_leave_requests h join public.business_leave_request_lines l on l.tenant_id=h.tenant_id and l.request_id=h.id and l.status='active' join public.business_staff st on st.tenant_id=h.tenant_id and st.id=h.staff_id where h.tenant_id=p_tenant and h.status='draft' and l.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or st.department=v->>'department')) or exists(select 1 from public.business_overtime_requests r join public.business_staff st on st.tenant_id=r.tenant_id and st.id=r.staff_id where r.tenant_id=p_tenant and r.status='draft' and r.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or st.department=v->>'department') and (v->>'project_id' is null or r.project_id=(v->>'project_id')::uuid)) then raise exception 'BUSINESS_UNPOSTED_DOCUMENTS';end if;
  if exists(select 1 from public.business_attendance_locks l where l.tenant_id=p_tenant and l.status='posted' and l.starts_on<=(v->>'ends_on')::date and l.ends_on>=(v->>'starts_on')::date and (coalesce(l.department,'')='' or coalesce(v->>'department','')='' or l.department=v->>'department') and (l.project_id is null or v->>'project_id' is null or l.project_id=(v->>'project_id')::uuid)) then raise exception 'BUSINESS_PERIOD_OVERLAP';end if;
  if exists(select 1 from public.business_timecards t join public.business_staff s on s.tenant_id=t.tenant_id and s.id=t.staff_id where t.tenant_id=p_tenant and t.status='draft' and t.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or s.department=v->>'department') and (v->>'project_id' is null or t.project_id=(v->>'project_id')::uuid)) or exists(select 1 from public.business_attendance_confirmations c join public.business_shift_assignments a on a.tenant_id=c.tenant_id and a.id=c.assignment_id join public.business_staff s on s.tenant_id=c.tenant_id and s.id=c.staff_id where c.tenant_id=p_tenant and c.status='draft' and a.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or s.department=v->>'department') and (v->>'project_id' is null or c.project_id=(v->>'project_id')::uuid)) then raise exception 'BUSINESS_UNPOSTED_DOCUMENTS';end if;
  select coalesce(sum(t.worked_hours+t.overtime_hours),0),md5(coalesce(string_agg(t.id::text||':'||t.row_version::text,'|' order by t.id),'')) into total,fingerprint from public.business_timecards t join public.business_staff s on s.tenant_id=t.tenant_id and s.id=t.staff_id where t.tenant_id=p_tenant and t.status='posted' and t.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or s.department=v->>'department') and (v->>'project_id' is null or t.project_id=(v->>'project_id')::uuid);
  fingerprint:=md5(fingerprint||coalesce((select string_agg('L:'||l.id::text||':'||l.row_version::text||':'||h.row_version::text,'|' order by l.id) from public.business_leave_request_lines l join public.business_leave_requests h on h.tenant_id=l.tenant_id and h.id=l.request_id and h.status='posted' join public.business_staff st on st.tenant_id=h.tenant_id and st.id=h.staff_id where l.tenant_id=p_tenant and l.status='active' and l.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or st.department=v->>'department')),'')||coalesce((select string_agg('OT:'||r.id::text||':'||r.row_version::text,'|' order by r.id) from public.business_overtime_requests r join public.business_staff st on st.tenant_id=r.tenant_id and st.id=r.staff_id where r.tenant_id=p_tenant and r.status='posted' and r.work_date between (v->>'starts_on')::date and (v->>'ends_on')::date and (coalesce(v->>'department','')='' or st.department=v->>'department') and (v->>'project_id' is null or r.project_id=(v->>'project_id')::uuid)),''));
  rows:=jsonb_build_array(jsonb_build_object('sourceName','Bảng công đã xác nhận','hours',total,'sourceHash',fingerprint));
 else raise exception 'BUSINESS_INVALID_INPUT';end case;
 if jsonb_array_length(rows)=0 then raise exception 'BUSINESS_ORDER_EMPTY';end if;
 return jsonb_build_object('rows',rows,'totalHours',total,'context',context);
end $$;
revoke all on function public.business_attendance_calculation(uuid,text,jsonb) from public,anon,authenticated,service_role;
